//! MMFF94 reference parameters and lookup rules.
//!
//! Atom properties, charges, bonds, angles, stretch-bend, torsions,
//! out-of-plane and van der Waals parameters, with the reference lookup
//! and equivalence rules. Atom typing and energy evaluation are left to
//! the caller. Energies are kcal/mol, lengths angstroms, angles degrees;
//! force constants retain the units of the original MMFF tables.
//!
//! The numbers are Merck's, taken from RDKit's copy as `THIRD_PARTY.md`
//! records. Nothing here is derived or rounded: a parameter table is only
//! useful if it is the same table everyone else is using.
//!
//! A few of Merck's fitted numbers land within a rounding of a mathematical
//! constant -- 0.3183 against 1/pi, 2.718 against e -- which the lint for
//! that would otherwise flag one table row at a time.
#![allow(clippy::approx_constant)]

/// What MMFF94 knows about an atom type before it looks at a molecule.
///
/// The whole published row is kept, not only the fields in use: it is one
/// table, and half a table invites the question of where the other half
/// went. The charge model reads `connections`, `aromatic` and
/// `single_bond_between_multiply_bonded`; the energy terms use the remaining fields
/// to choose parameters.
#[allow(dead_code)]
#[derive(Debug, Clone, Copy)]
pub struct TypeProperties {
    /// The element, as an atomic number.
    pub atomic_number: u8,
    /// How many connections the type is defined for, which is the `M` of the
    /// charge formula.
    pub connections: u8,
    /// The valence the type carries.
    pub valence: u8,
    /// Whether the atom brings a lone pair into a pi system.
    pub lone_pair: bool,
    /// How the type multiply bonds: 1 for a single multiple bond, 2 for a
    /// member of a delocalized system, 3 for the triple-bonded cases.
    pub multiple_bonds: u8,
    /// Whether the type is an aromatic one.
    pub aromatic: bool,
    /// Whether the type sits at a linear centre.
    pub linear: bool,
    /// Whether a single bond between two such types is a "single bond between
    /// multiply bonded atoms" -- MMFF's bond type 1, which has parameters of
    /// its own.
    pub single_bond_between_multiply_bonded: bool,
}

/// Partial bond charge increment and formal-charge adjustment, per type.
#[derive(Debug, Clone, Copy)]
pub struct ChargeProperties {
    /// Used where a pair of types has no bond charge increment of its own:
    /// the increment is then the difference of the two partial ones.
    pub partial_increment: f64,
    /// How much of a neighbour's formal charge this type takes on.
    pub formal_charge_adjustment: f64,
}

