/// What MMFF94 says about a type, or `None` for one it does not assign.
pub fn properties(number: u8) -> Option<&'static TypeProperties> {
    PROPERTIES
        .binary_search_by_key(&number, |(kind, _)| *kind)
        .ok()
        .map(|index| &PROPERTIES[index].1)
}

/// The charge properties of a type.
pub fn charge_properties(number: u8) -> Option<&'static ChargeProperties> {
    CHARGE_PROPERTIES
        .binary_search_by_key(&number, |(kind, _)| *kind)
        .ok()
        .map(|index| &CHARGE_PROPERTIES[index].1)
}

/// The bond charge increment moving charge onto the atom of type `first`,
/// or `None` where this pair of types has none and the partial increments
/// have to stand in for it.
pub fn bond_charge_increment(bond_type: u8, first: u8, second: u8) -> Option<f64> {
    let (low, high, sign) = if first > second {
        (second, first, 1.0)
    } else {
        (first, second, -1.0)
    };
    BOND_CHARGE_INCREMENTS
        .binary_search_by_key(&(low, high, bond_type), |&(i, j, kind, _)| (i, j, kind))
        .ok()
        .map(|index| sign * BOND_CHARGE_INCREMENTS[index].3)
}

/// A bond's ideal length and force constant.
#[derive(Debug, Clone, Copy)]
pub struct BondParameters {
    pub force_constant: f64,
    pub length: f64,
}

/// An angle's ideal value and force constant. A force constant of zero means
/// the table has the geometry but not the stiffness, and the empirical rule
/// supplies the rest.
#[derive(Debug, Clone, Copy)]
pub struct AngleParameters {
    pub force_constant: f64,
    pub angle: f64,
}

/// How much the two bonds of an angle couple to its bending.
#[derive(Debug, Clone, Copy)]
pub struct StretchBendParameters {
    pub first: f64,
    pub second: f64,
}

/// A torsion's three-fold Fourier coefficients.
#[derive(Debug, Clone, Copy)]
pub struct TorsionParameters {
    pub v1: f64,
    pub v2: f64,
    pub v3: f64,
}

/// What an element contributes to the empirical bond rule: a covalent radius
/// and a Pauling electronegativity.
#[derive(Debug, Clone, Copy)]
pub struct CovalentRadiusElectronegativity {
    pub radius: f64,
    pub electronegativity: f64,
}

/// The Herschbach-Laurie form of Badger's rule, per pair of periodic rows.
#[derive(Debug, Clone, Copy)]
pub struct HerschbachLaurie {
    pub a: f64,
    pub d: f64,
}

/// An atom type's van der Waals parameters, in MMFF's own polarizability
/// form rather than as a radius and a well depth.
#[derive(Debug, Clone, Copy)]
pub struct VanDerWaalsParameters {
    pub polarizability: f64,
    pub electrons: f64,
    pub scale: f64,
    pub factor: f64,
    /// `b'D'` for a hydrogen-bond donor, `b'A'` for an acceptor, `b'-'` for
    /// neither. Donor-acceptor pairs get a tightened minimum and a shallower
    /// well.
    pub donor_acceptor: u8,
}

/// The constants at the head of the van der Waals table: the exponent of
/// the radius rule, and the terms that shrink a donor-acceptor pair.
pub const VDW_POWER: f64 = 0.25;
pub const VDW_B: f64 = 0.2;
pub const VDW_BETA: f64 = 12.0;
pub const VDW_DONOR_ACCEPTOR_RADIUS: f64 = 0.8;
pub const VDW_DONOR_ACCEPTOR_WELL: f64 = 0.5;

