/// The types MMFF94 counts as aromatic when its torsion rule asks.
#[rustfmt::skip]
static AROMATIC_TYPES: [u8; 17] = [37, 38, 39, 44, 58, 59, 63, 64, 65, 66, 69, 76, 78, 79, 80, 81, 82];

/// Whether an atom type belongs to MMFF's aromatic type set.
pub fn is_aromatic_type(number: u8) -> bool {
    AROMATIC_TYPES.contains(&number)
}

/// Van der Waals parameters for an atom type, or `None` if unsupported.
pub fn van_der_waals(number: u8) -> Option<&'static VanDerWaalsParameters> {
    VAN_DER_WAALS
        .binary_search_by_key(&number, |(kind, _)| *kind)
        .ok()
        .map(|index| &VAN_DER_WAALS[index].1)
}

/// The stand-in for a type at one of the four equivalence levels, the last
/// of which is the wild card.
///
/// `level` must be in `0..4`; a known type and an out-of-range level panic.
/// An unknown type maps to the wildcard (`0`).
pub fn equivalent(number: u8, level: usize) -> u8 {
    EQUIVALENCE
        .binary_search_by_key(&number, |(kind, _)| *kind)
        .ok()
        .map_or(0, |index| EQUIVALENCE[index].1[level])
}

/// Exact bond parameters, independent of the order of the endpoint types.
pub fn bond(bond_type: u8, first: u8, second: u8) -> Option<&'static BondParameters> {
    let key = (first.min(second), first.max(second), bond_type);
    BONDS
        .binary_search_by_key(&key, |&(i, j, kind, _)| (i, j, kind))
        .ok()
        .map(|index| &BONDS[index].3)
}

/// The reference bond between two elements, which the empirical rule scales.
pub fn element_bond(first: u8, second: u8) -> Option<&'static BondParameters> {
    let key = (first.min(second), first.max(second));
    ELEMENT_BONDS
        .binary_search_by_key(&key, |&(i, j, _)| (i, j))
        .ok()
        .map(|index| &ELEMENT_BONDS[index].2)
}

/// Herschbach-Laurie parameters for two model-specific periodic-row indices.
pub fn herschbach_laurie(first: u8, second: u8) -> Option<&'static HerschbachLaurie> {
    let key = (first.min(second), first.max(second));
    HERSCHBACH_LAURIE
        .binary_search_by_key(&key, |&(i, j, _)| (i, j))
        .ok()
        .map(|index| &HERSCHBACH_LAURIE[index].2)
}

/// MMFF empirical radius (Å) and electronegativity for an element.
pub fn covalent_radius(atomic_number: u8) -> Option<&'static CovalentRadiusElectronegativity> {
    COVALENT_RADII
        .binary_search_by_key(&atomic_number, |(number, _)| *number)
        .ok()
        .map(|index| &COVALENT_RADII[index].1)
}

/// The angle parameters for these three types, trying each equivalence level
/// in turn: the exact types first, then progressively vaguer stand-ins for
/// the two outer atoms, with the central one always exact.
pub fn angle(angle_type: u8, first: u8, central: u8, last: u8) -> Option<&'static AngleParameters> {
    (0..4).find_map(|level| {
        let one = equivalent(first, level);
        let other = equivalent(last, level);
        let key = (central, one.min(other), one.max(other), angle_type);
        ANGLES
            .binary_search_by_key(&key, |&(j, i, k, kind, _)| (j, i, k, kind))
            .ok()
            .map(|index| &ANGLES[index].4)
    })
}

/// The stretch-bend parameters, and whether the pair comes back the other
/// way round -- the table stores each angle with its outer types in
/// ascending order, and the two constants are not interchangeable.
pub fn stretch_bend(
    stretch_bend_type: u8,
    first: u8,
    central: u8,
    last: u8,
    first_bond_type: u8,
    last_bond_type: u8,
) -> Option<(bool, &'static StretchBendParameters)> {
    let swapped = if first > last {
        true
    } else if first == last {
        first_bond_type < last_bond_type
    } else {
        false
    };
    let key = (central, first.min(last), first.max(last), stretch_bend_type);
    STRETCH_BENDS
        .binary_search_by_key(&key, |&(j, i, k, kind, _)| (j, i, k, kind))
        .ok()
        .map(|index| (swapped, &STRETCH_BENDS[index].4))
}

/// The stretch-bend fallback for an angle whose types have no entry, keyed
/// on the three atoms' periodic rows.
pub fn default_stretch_bend(
    first_row: u8,
    central_row: u8,
    last_row: u8,
) -> Option<(bool, &'static StretchBendParameters)> {
    let swapped = first_row > last_row;
    let key = (
        first_row.min(last_row),
        central_row,
        first_row.max(last_row),
    );
    DEFAULT_STRETCH_BENDS
        .binary_search_by_key(&key, |&(i, j, k, _)| (i, j, k))
        .ok()
        .map(|index| (swapped, &DEFAULT_STRETCH_BENDS[index].3))
}

/// The out-of-plane force constant for a centre and its three neighbours,
/// again trying each equivalence level in turn.
pub fn out_of_plane(central: u8, first: u8, second: u8, third: u8) -> Option<f64> {
    (0..4).find_map(|level| {
        let mut around = [
            equivalent(first, level),
            equivalent(second, level),
            equivalent(third, level),
        ];
        around.sort_unstable();
        let key = (central, around[0], around[1], around[2]);
        OUT_OF_PLANE
            .binary_search_by_key(&key, |&(j, i, k, l, _)| (j, i, k, l))
            .ok()
            .map(|index| OUT_OF_PLANE[index].4)
    })
}

/// One lookup in the torsion table, with the four types already reduced to
/// the level being tried.
fn torsion_exact(
    torsion_type: u8,
    first: u8,
    second: u8,
    third: u8,
    fourth: u8,
) -> Option<&'static TorsionParameters> {
    // The table stores each torsion read from its lower-numbered central
    // type; reading it the other way round reverses the outer pair too.
    let (i, j, k, l) = if second > third {
        (fourth, third, second, first)
    } else if second == third && first > fourth {
        (fourth, second, third, first)
    } else {
        (first, second, third, fourth)
    };
    let key = (j, k, i, l, torsion_type);
    TORSIONS
        .binary_search_by_key(&key, |&(j, k, i, l, kind, _)| (j, k, i, l, kind))
        .ok()
        .map(|index| &TORSIONS[index].5)
}

/// The torsion parameters, and the type they were found under.
///
/// Five stages, as MMFF.IV describes them: the exact types, then the level-2
/// stand-ins, then two "half wild-card" stages that vague one end and not
/// the other, then both ends. A torsion in a five-ring that finds nothing
/// falls back to the type it would have had outside the ring, which is not
/// in the papers at all -- it is in RDKit because the validation suite
/// needs it.
pub fn torsion(
    torsion_type: u8,
    secondary_type: u8,
    first: u8,
    second: u8,
    third: u8,
    fourth: u8,
) -> Option<(u8, &'static TorsionParameters)> {
    let mut found: Option<&'static TorsionParameters> = None;
    let mut kind = torsion_type;
    let mut stage = 0;
    let mut stages = 5;

    // A transcription of RDKit's loop, which is stranger than the paper: a
    // fifth stage that is not another level but another *type*, retrying the
    // whole ladder under the type this torsion would have had outside its
    // ring. It runs when the first four stages found nothing, and also when
    // they only found something at the wild-card stage -- in which case the
    // second type's answer, if it has one, wins.
    // `stages == 5` in the second clause is this crate's own: without it the
    // retry pass can reach a fifth level that does not exist, which in C++
    // reads off the end of the equivalence array rather than stopping. When
    // both types have run out of levels, the empirical rule is the answer.
    while (stage < stages && (found.is_none() || stages == 4))
        || (stage == 4 && stages == 5 && torsion_type == 5 && secondary_type != 0)
    {
        if stages == 5 && stage == 4 {
            stages = 4;
            stage = 0;
            kind = secondary_type;
        }
        // Stages three and four vague one end of the torsion and leave the
        // other exact, which is what MMFF.IV calls a half wild card.
        let (near, far) = match stage {
            1 => (1, 3),
            2 => (3, 1),
            other => (other, other),
        };
        if let Some(parameters) = torsion_exact(
            kind,
            equivalent(first, near),
            second,
            third,
            equivalent(fourth, far),
        ) {
            found = Some(parameters);
            if stages == 4 {
                break;
            }
        }
        stage += 1;
    }

    found.map(|parameters| (kind, parameters))
}

/// MMFF's millidyne-angstrom to kcal/mol conversion, retained at its fitted precision.
/// This is a model convention, not a replacement for a modern SI conversion.
pub const MDYNE_ANGSTROM_TO_KCAL_PER_MOL: f64 = 143.9325;
/// MMFF electrostatic prefactor in kcal Å / (mol e²).
pub const COULOMB_KCAL_ANGSTROM_PER_MOL: f64 = 332.0716;
/// Electrostatic scale for atoms separated by three bonds.
pub const ELECTROSTATIC_ONE_FOUR_SCALE: f64 = 0.75;
/// Electrostatic distance buffer in angstroms.
pub const ELECTROSTATIC_BUFFER_ANGSTROM: f64 = 0.05;
/// Bond-stretch cubic coefficient in inverse angstroms.
pub const BOND_CUBIC: f64 = -2.0;
/// Quartic multiplier of the squared cubic coefficient (dimensionless).
pub const BOND_QUARTIC: f64 = 7.0 / 12.0;
/// Angle-bend cubic coefficient per degree.
pub const ANGLE_CUBIC: f64 = -0.006981317;
/// Dimensionless near-distance buffer in the buffered 14-7 potential.
pub const VDW_NEAR_BUFFER: f64 = 1.07;
/// Dimensionless far-distance buffer in the buffered 14-7 potential.
pub const VDW_FAR_BUFFER: f64 = 1.12;
/// Prefactor for the MMFF van der Waals well-depth combination rule.
/// Produces kcal/mol with the tabulated polarizabilities and distances in Å.
pub const VDW_WELL_PREFACTOR: f64 = 181.16;
/// Bond-radius shrinkage coefficient for hydrogen-containing bonds, in Å.
pub const BOND_SHRINKAGE_HYDROGEN: f64 = 0.050;
/// Bond-radius shrinkage coefficient for other bonds, in Å.
pub const BOND_SHRINKAGE_HEAVY: f64 = 0.085;
/// Exponent of the electronegativity difference in MMFF.V equation 18.
pub const BOND_ELECTRONEGATIVITY_EXPONENT: f64 = 1.4;

/// Effective outer-atom charge in MMFF.V equation 20; zero when unsupported.
pub fn empirical_angle_charge(atomic_number: u8) -> f64 {
    match atomic_number {
        1 => 1.395,
        6 => 2.494,
        7 => 2.711,
        8 => 3.045,
        9 => 2.847,
        14 => 2.350,
        15 => 2.350,
        16 => 2.980,
        17 => 2.909,
        35 => 3.017,
        53 => 3.086,
        _ => 0.0,
    }
}

/// Central-atom shell factor in MMFF.V equation 20; zero when unsupported.
pub fn empirical_angle_shell(atomic_number: u8) -> f64 {
    match atomic_number {
        6 => 1.016,
        7 => 1.113,
        8 => 1.337,
        14 => 0.811,
        15 => 1.068,
        16 => 1.249,
        17 => 1.078,
        _ => 0.0,
    }
}

/// MMFF.IV per-element (U, V, W) torsion parameters; zeros when unsupported.
pub fn empirical_torsion_constants(atomic_number: u8) -> (f64, f64, f64) {
    match atomic_number {
        6 => (2.0, 2.12, 0.0),
        7 => (2.0, 1.5, 0.0),
        8 => (2.0, 0.2, 2.0),
        14 => (1.25, 1.22, 0.0),
        15 => (1.25, 2.40, 0.0),
        16 => (1.25, 0.49, 8.0),
        _ => (0.0, 0.0, 0.0),
    }
}

/// Base coefficient in the MMFF.V empirical angle force-constant rule.
pub const EMPIRICAL_ANGLE_PREFACTOR: f64 = 1.75;
/// Empirical angle-force softening for three-membered rings.
pub const THREE_RING_ANGLE_SCALE: f64 = 0.05;
/// Empirical angle-force softening for four-membered rings.
pub const FOUR_RING_ANGLE_SCALE: f64 = 0.85;

#[cfg(test)]
mod tests {
    use super::*;

    /// Every binary search requires strictly increasing keys; a misplaced row
    /// silently makes valid force-field parameters unreachable.
    #[test]
    fn lookup_tables_have_sorted_unique_keys() {
        fn sorted<K: Ord>(keys: impl Iterator<Item = K>) {
            let keys: Vec<_> = keys.collect();
            assert!(keys.windows(2).all(|w| w[0] < w[1]));
        }
        sorted(PROPERTIES.iter().map(|x| x.0));
        sorted(CHARGE_PROPERTIES.iter().map(|x| x.0));
        sorted(BOND_CHARGE_INCREMENTS.iter().map(|x| (x.0, x.1, x.2)));
        sorted(VAN_DER_WAALS.iter().map(|x| x.0));
        sorted(EQUIVALENCE.iter().map(|x| x.0));
        sorted(BONDS.iter().map(|x| (x.0, x.1, x.2)));
        sorted(ELEMENT_BONDS.iter().map(|x| (x.0, x.1)));
        sorted(HERSCHBACH_LAURIE.iter().map(|x| (x.0, x.1)));
        sorted(COVALENT_RADII.iter().map(|x| x.0));
        sorted(ANGLES.iter().map(|x| (x.0, x.1, x.2, x.3)));
        sorted(STRETCH_BENDS.iter().map(|x| (x.0, x.1, x.2, x.3)));
        sorted(DEFAULT_STRETCH_BENDS.iter().map(|x| (x.0, x.1, x.2)));
        sorted(OUT_OF_PLANE.iter().map(|x| (x.0, x.1, x.2, x.3)));
        sorted(TORSIONS.iter().map(|x| (x.0, x.1, x.2, x.3, x.4)));
    }

    #[test]
    fn bond_lookup_is_symmetric_and_charge_transfer_is_antisymmetric() {
        for &(first, second, kind, ref row) in &BONDS {
            let forward = bond(kind, first, second).unwrap();
            let reverse = bond(kind, second, first).unwrap();
            assert!(std::ptr::eq(forward, row));
            assert!(std::ptr::eq(forward, reverse));
            assert!(row.length > 0.0 && row.force_constant > 0.0);
        }
        for &(first, second, kind, _) in &BOND_CHARGE_INCREMENTS {
            let forward = bond_charge_increment(kind, first, second).unwrap();
            let reverse = bond_charge_increment(kind, second, first).unwrap();
            assert_eq!(forward, -reverse);
        }
    }

    #[test]
    fn unknown_types_do_not_acquire_reference_parameters() {
        for number in [0, 100, u8::MAX] {
            assert!(properties(number).is_none());
            assert!(van_der_waals(number).is_none());
            assert!(bond(0, number, number).is_none());
            assert_eq!(equivalent(number, 0), 0);
        }
        for &(number, _) in &PROPERTIES {
            assert!(charge_properties(number).is_some());
            assert!(van_der_waals(number).is_some());
            assert_eq!(equivalent(number, 0), number);
        }
    }
}
